mapper.select:
select id, post_id, title, content, category_id, stu_number, username, user_image,
       view_count, like_count, comment_count, status, create_time, update_time
from chat_app.forum_post


        and title like concat('%', #{title}, '%')


        and category_id = #{categoryId}


        and stu_number = #{stuNumber}


        and status = #{status}


order by create_time desc
